async function ensureAssessmentBudgetPotColumn(executor = pool) {
  if (!executor || typeof executor.query !== 'function') return false;
  if (hasAssessmentBudgetPotColumn === true) return true;
  try {
    const [rows] = await executor.query(
      `SELECT COUNT(*) AS cnt
         FROM information_schema.columns
        WHERE table_schema = DATABASE()
          AND table_name = 'iset_case_assessment'
          AND column_name = 'intervention_budget_pot_id'
        LIMIT 1`
    );
    const exists = Array.isArray(rows) && rows.length && Number(rows[0].cnt) > 0;
    if (exists) {
      hasAssessmentBudgetPotColumn = true;
      return true;
    }
    // Do not mutate schema here; simply mark missing so callers can fall back or raise a clear error.
    hasAssessmentBudgetPotColumn = false;
    return false;
  } catch (err) {
    console.warn('[assessment] failed to inspect assessment table columns:', err?.message || err);
  }
  hasAssessmentBudgetPotColumn = false;
  return false;
}

function loadChecklistConfigFromFile(filePath = CHECKLIST_FALLBACK_PATH) {
  try {
    const raw = fs.readFileSync(filePath, 'utf8');
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    return parsed || null;
  } catch (err) {
    console.warn('[checklist] fallback file load failed', err?.message || err);
    return null;
  }
}

function loadChecklistTemplate(filePath) {
  if (!filePath) return null;
  if (checklistTemplateCache.has(filePath)) {
    return checklistTemplateCache.get(filePath);
  }
  const parsed = loadChecklistConfigFromFile(filePath);
  if (parsed) {
    checklistTemplateCache.set(filePath, parsed);
  }
  return parsed;
}

async function loadChecklistConfig(key = CHECKLIST_KEY) {
  const now = Date.now();
  const cacheKey = key || CHECKLIST_KEY;
  const cached = checklistCacheByKey.get(cacheKey);
  if (cached?.data && now - cached.ts < CHECKLIST_CACHE_TTL_MS) {
    return cached.data;
  }
  try {
    const [rows] = await pool.query(
      'SELECT v FROM iset_runtime_config WHERE scope = ? AND k = ? LIMIT 1',
      [CHECKLIST_SCOPE, cacheKey]
    );
    if (!rows || !rows.length) {
      checklistCacheByKey.set(cacheKey, { ts: now, data: null });
      return null;
    }
    const raw = rows[0].v;
    const parsed = typeof raw === 'object' ? raw : JSON.parse(raw);
    const data = parsed || null;
    checklistCacheByKey.set(cacheKey, { ts: now, data });
    return data;
  } catch (err) {
    console.warn('[checklist] load failed', err?.message || err);
    checklistCacheByKey.set(cacheKey, { ts: now, data: null });
    return null;
  }
}

function normaliseChecklistId(value) {
  return String(value || '').trim().toLowerCase().replace(/[\s_]+/g, '-');
}

function normaliseChecklistStatus(value) {
  return String(value || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
}

function normaliseChecklistItem(raw) {
  if (!raw || typeof raw !== 'object') return null;
  const id = String(raw.id || '').trim();
  const label = String(raw.label || '').trim();
  if (!id || !label) return null;
  const documentTypes = Array.isArray(raw.documentTypes)
    ? raw.documentTypes.map(String).map(t => t.trim()).filter(Boolean)
    : [];
  const sources = Array.isArray(raw.sources)
    ? raw.sources.map(String).map(s => s.trim()).filter(Boolean)
    : [];
  const minCountValue = Number(raw.minCount);
  const minCount = Number.isFinite(minCountValue) && minCountValue > 0 ? minCountValue : undefined;
  const notes = typeof raw.notes === 'string' ? raw.notes.trim() : '';
  return {
    ...raw,
    id,
    label,
    required: raw.required !== false,
    documentTypes,
    sources,
    ...(minCount ? { minCount } : {}),
    ...(notes ? { notes } : {})
  };
}

function normaliseChecklistGate(raw) {
  if (!raw || typeof raw !== 'object') return null;
  const id = String(raw.id || '').trim();
  const label = String(raw.label || '').trim();
  if (!id || !label) return null;
  const statusScope = String(raw.statusScope || 'application').trim();
  const statuses = Array.isArray(raw.statuses)
    ? raw.statuses.map(s => String(s).trim()).filter(Boolean)
    : [];
  const items = Array.isArray(raw.items) ? raw.items.map(normaliseChecklistItem).filter(Boolean) : [];
  return {
    ...raw,
    id,
    label,
    statusScope: statusScope || 'application',
    statuses,
    items
  };
}

function moveChecklistItem(config, { itemId, fromGateId, toGateId }) {
  if (!config || !Array.isArray(config.gates)) return config;
  const fromGate = config.gates.find(gate => gate && gate.id === fromGateId);
  const toGate = config.gates.find(gate => gate && gate.id === toGateId);
  if (!fromGate || !toGate) return config;
  const fromItems = Array.isArray(fromGate.items) ? fromGate.items : [];
  const toItems = Array.isArray(toGate.items) ? toGate.items : [];
  const normalizedTargetId = normaliseChecklistId(itemId);
  const index = fromItems.findIndex(item => normaliseChecklistId(item?.id) === normalizedTargetId);
  if (index < 0) return config;
  const [moved] = fromItems.splice(index, 1);
  const alreadyExists = toItems.some(item => normaliseChecklistId(item?.id) === normalizedTargetId);
  if (!alreadyExists && moved) {
    toItems.push(moved);
  }
  fromGate.items = fromItems;
  toGate.items = toItems;
  return config;
}

function applyChecklistMigrations(config) {
  if (!config || !Array.isArray(config.gates)) return config;
  moveChecklistItem(config, {
    itemId: 'client-acknowledgement',
    fromGateId: 'submit_assessment',
    toGateId: 'enable_funding'
  });
  return config;
}

function applyChecklistTemplate(rawItems = [], templateConfig) {
  const cleanedItems = Array.isArray(rawItems) ? rawItems.map(normaliseChecklistItem).filter(Boolean) : [];
  if (!templateConfig || !Array.isArray(templateConfig.gates)) {
    return {
      id: templateConfig?.id || 'checklist',
      label: templateConfig?.label || 'Checklist',
      version: templateConfig?.version || '',
      gates: [{
        id: 'default',
        label: 'Checklist',
        statusScope: 'application',
        statuses: [],
        items: cleanedItems
      }]
    };
  }
  const itemsById = new Map(cleanedItems.map(item => [normaliseChecklistId(item.id), item]));
  const usedIds = new Set();
  const gates = templateConfig.gates.map(gate => {
    const gateItems = Array.isArray(gate.items)
      ? gate.items.map(item => {
        const key = normaliseChecklistId(item.id);
        const match = itemsById.get(key);
        if (match) usedIds.add(key);
        return match || null;
      }).filter(Boolean)
      : [];
    return {
      ...gate,
      items: gateItems
    };
  });
  const extras = cleanedItems.filter(item => !usedIds.has(normaliseChecklistId(item.id)));
  if (extras.length && gates.length) {
    gates[0] = {
      ...gates[0],
      items: [...(gates[0].items || []), ...extras]
    };
  }
  return {
    ...templateConfig,
    gates
  };
}

function coerceChecklistConfig(raw, templateConfig) {
  if (!raw || typeof raw !== 'object') {
    return applyChecklistMigrations(templateConfig || null);
  }
  if (Array.isArray(raw.gates)) {
    const gates = raw.gates.map(normaliseChecklistGate).filter(Boolean);
    const next = {
      ...raw,
      id: raw.id || templateConfig?.id || 'checklist',
      label: raw.label || templateConfig?.label || 'Checklist',
      version: raw.version || templateConfig?.version || '',
      gates
    };
    return applyChecklistMigrations(next);
  }
  if (Array.isArray(raw.items)) {
    return applyChecklistMigrations(applyChecklistTemplate(raw.items, templateConfig || null));
  }
  return applyChecklistMigrations(templateConfig || raw || null);
}

function resolveChecklistGate(checklist, { applicationStatus, caseStatus, interventionStatus, stageId } = {}) {
  if (!checklist || !Array.isArray(checklist.gates)) return null;
  const normalizedStage = stageId ? normaliseChecklistId(stageId) : '';
  if (normalizedStage) {
    const stageMatch = checklist.gates.find(
      gate => gate && normaliseChecklistId(gate.id) === normalizedStage
    );
    if (stageMatch) return stageMatch;
  }
  for (const gate of checklist.gates) {
    if (!gate || !Array.isArray(gate.items)) continue;
    const statuses = Array.isArray(gate.statuses) ? gate.statuses : [];
    if (!statuses.length) return gate;
    const scope = gate.statusScope || 'application';
    const currentStatus =
      scope === 'case' ? caseStatus :
      scope === 'intervention' ? interventionStatus :
      applicationStatus;
    if (!currentStatus) continue;
    const normalizedCurrent = normaliseChecklistStatus(currentStatus);
    const matches = statuses.some(status => normaliseChecklistStatus(status) === normalizedCurrent);
    if (matches) return gate;
  }
  return null;
}

function clearChecklistCache(key) {
  if (!key) {
    checklistCacheByKey.clear();
    return;
  }
  checklistCacheByKey.delete(key);
}

async function loadDocumentTypeScopeMap(executor = pool) {
  const map = new Map();
  try {
    const [rows] = await executor.query(
      `SELECT code, COALESCE(scope, 'application') AS scope
         FROM document_type
        WHERE is_active = 1`
    );
    rows.forEach(row => {
      if (row && row.code) {
        map.set(row.code, row.scope || 'application');
      }
    });
  } catch (err) {
    console.warn('[document-types] scope map load failed', err?.message || err);
  }
  return map;
}

const normalizeIdList = value => {
  if (!value) return [];
  if (Array.isArray(value)) {
    return Array.from(new Set(
      value.map(entry => normalisePositiveInteger(entry)).filter(Boolean)
    ));
  }
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return [];
    if (trimmed.startsWith('[')) {
      try {
        const parsed = JSON.parse(trimmed);
        if (Array.isArray(parsed)) {
          return normalizeIdList(parsed);
        }
      } catch (_) {
        // fall through to comma parsing
      }
    }
    return Array.from(new Set(
      trimmed
        .split(',')
        .map(token => normalisePositiveInteger(token))
        .filter(Boolean)
    ));
  }
  const single = normalisePositiveInteger(value);
  return single ? [single] : [];
};

async function resolveClientIdFromApplicantUserId(applicantUserId, connection = pool) {
  const normalizedUserId = normalisePositiveInteger(applicantUserId);
  if (!normalizedUserId) return null;
  const [[row]] = await connection.query(
    `SELECT cl.id
       FROM user u
       JOIN client cl ON cl.applicant_cognito_sub = u.cognito_sub
      WHERE u.id = ?
      LIMIT 1`,
    [normalizedUserId]
  );
  return row?.id ? Number(row.id) : null;
}

async function resolveClientIdFromCaseId(caseId, connection = pool) {
  const normalizedCaseId = normalisePositiveInteger(caseId);
  if (!normalizedCaseId) return null;
  const [[row]] = await connection.query(
    'SELECT client_id FROM iset_case WHERE id = ? LIMIT 1',
    [normalizedCaseId]
  );
  return row?.client_id ? Number(row.client_id) : null;
}

async function resolveClientIdFromActionPlanId(actionPlanId, connection = pool) {
  const normalizedPlanId = normalisePositiveInteger(actionPlanId);
  if (!normalizedPlanId) return null;
  const [[row]] = await connection.query(
    `SELECT c.client_id
       FROM iset_case_action_plan ap
       JOIN iset_case c ON c.id = ap.case_id
      WHERE ap.id = ?
      LIMIT 1`,
    [normalizedPlanId]
  );
  return row?.client_id ? Number(row.client_id) : null;
}

async function resolveClientIdFromApplicationId(applicationId, connection = pool) {
  const normalizedApplicationId = normalisePositiveInteger(applicationId);
  if (!normalizedApplicationId) return null;
  const [[caseRow]] = await connection.query(
    'SELECT client_id FROM iset_case WHERE application_id = ? LIMIT 1',
    [normalizedApplicationId]
  );
  if (caseRow?.client_id) return Number(caseRow.client_id);
  const [[userRow]] = await connection.query(
    `SELECT u.id, u.cognito_sub
       FROM iset_application a
       JOIN iset_application_submission s ON s.id = a.submission_id
       JOIN user u ON u.id = s.user_id
      WHERE a.id = ?
      LIMIT 1`,
    [normalizedApplicationId]
  );
  if (!userRow?.cognito_sub) return null;
  const [[clientRow]] = await connection.query(
    'SELECT id FROM client WHERE applicant_cognito_sub = ? LIMIT 1',
    [userRow.cognito_sub]
  );
  return clientRow?.id ? Number(clientRow.id) : null;
}

async function resolveClientIdForDocument({
  applicantUserId = null,
  caseId = null,
  actionPlanId = null,
  applicationId = null,
  connection = pool,
} = {}) {
  const candidates = [];
  const pushCandidate = (source, value) => {
    const normalized = Number(value);
    if (!Number.isFinite(normalized) || normalized <= 0) return;
    candidates.push({ source, id: normalized });
  };
  if (actionPlanId) {
    const clientId = await resolveClientIdFromActionPlanId(actionPlanId, connection);
    if (clientId) pushCandidate('action_plan', clientId);
  }
  if (caseId) {
    const clientId = await resolveClientIdFromCaseId(caseId, connection);
    if (clientId) pushCandidate('case', clientId);
  }
  if (applicationId) {
    const clientId = await resolveClientIdFromApplicationId(applicationId, connection);
    if (clientId) pushCandidate('application', clientId);
  }
  if (applicantUserId) {
    const clientId = await resolveClientIdFromApplicantUserId(applicantUserId, connection);
    if (clientId) pushCandidate('applicant', clientId);
  }
  const unique = Array.from(new Set(candidates.map(entry => entry.id)));
  if (unique.length > 1) {
    const err = new Error('client_id_mismatch');
    err.code = 'client_id_mismatch';
    err.details = candidates;
    throw err;
  }
  return unique.length ? unique[0] : null;
}

