async function resolveActionPlanIdForInterventions({ interventionIds, connection = pool } = {}) {
  const ids = Array.from(new Set((interventionIds || []).map(id => Number(id)).filter(Number.isFinite)));
  if (!ids.length) return null;
  const placeholders = ids.map(() => '?').join(',');
  const [rows] = await connection.query(
    `SELECT id, action_plan_id
       FROM iset_case_intervention
      WHERE id IN (${placeholders})`,
    ids
  );
  if (!rows.length) {
    const err = new Error('interventions_not_found');
    err.code = 'interventions_not_found';
    throw err;
  }
  const rowMap = new Map(rows.map(row => [Number(row.id), row]));
  const missing = ids.filter(id => !rowMap.has(id));
  if (missing.length) {
    const err = new Error('interventions_not_found');
    err.code = 'interventions_not_found';
    err.details = missing;
    throw err;
  }
  const planIds = Array.from(new Set(rows.map(row => row.action_plan_id).filter(Boolean)));
  if (planIds.length !== 1) {
    const err = new Error('interventions_multi_plan');
    err.code = 'interventions_multi_plan';
    err.details = planIds;
    throw err;
  }
  return Number(planIds[0]);
}

async function ensureInterventionsBelongToActionPlan({
  actionPlanId,
  interventionIds,
  connection = pool,
} = {}) {
  const normalizedPlanId = normalisePositiveInteger(actionPlanId);
  const ids = Array.from(new Set((interventionIds || []).map(id => Number(id)).filter(Number.isFinite)));
  if (!ids.length) return [];
  if (!normalizedPlanId) {
    const err = new Error('action_plan_required');
    err.code = 'action_plan_required';
    throw err;
  }
  const placeholders = ids.map(() => '?').join(',');
  const [rows] = await connection.query(
    `SELECT id, action_plan_id
       FROM iset_case_intervention
      WHERE id IN (${placeholders})`,
    ids
  );
  const rowMap = new Map(rows.map(row => [Number(row.id), row]));
  const missing = ids.filter(id => !rowMap.has(id));
  if (missing.length) {
    const err = new Error('interventions_not_found');
    err.code = 'interventions_not_found';
    err.details = missing;
    throw err;
  }
  const mismatched = rows
    .filter(row => Number(row.action_plan_id) !== Number(normalizedPlanId))
    .map(row => row.id);
  if (mismatched.length) {
    const err = new Error('interventions_plan_mismatch');
    err.code = 'interventions_plan_mismatch';
    err.details = mismatched;
    throw err;
  }
  return ids;
}

async function updateDocumentInterventionLinks({
  documentId,
  interventionIds = [],
  connection = pool,
} = {}) {
  const normalizedDocId = normalisePositiveInteger(documentId);
  if (!normalizedDocId) return;
  const ids = Array.from(new Set((interventionIds || []).map(id => Number(id)).filter(Number.isFinite)));
  await connection.query(
    'DELETE FROM iset_document_intervention WHERE document_id = ?',
    [normalizedDocId]
  );
  if (!ids.length) return;
  const values = ids.map(id => [normalizedDocId, id]);
  await connection.query(
    'INSERT INTO iset_document_intervention (document_id, intervention_id, created_at) VALUES ?',
    [values.map(entry => [...entry, new Date()])]
  );
}

async function fetchDocumentInterventionMap({ documentIds = [], connection = pool } = {}) {
  const ids = Array.from(new Set((documentIds || []).map(id => Number(id)).filter(Number.isFinite)));
  const map = new Map();
  if (!ids.length) return map;
  const placeholders = ids.map(() => '?').join(',');
  const [rows] = await connection.query(
    `SELECT document_id, intervention_id
       FROM iset_document_intervention
      WHERE document_id IN (${placeholders})`,
    ids
  );
  rows.forEach(row => {
    const docId = Number(row.document_id);
    const interventionId = Number(row.intervention_id);
    if (!Number.isFinite(docId) || !Number.isFinite(interventionId)) return;
    if (!map.has(docId)) {
      map.set(docId, []);
    }
    map.get(docId).push(interventionId);
  });
  return map;
}

async function loadApplicationAnswers({ applicantId = null, applicationId = null }) {
  try {
    let row = null;
    let caseRow = null;
    let caseMeta = { status: null, application_status: null };
    if (applicationId) {
      const [[app]] = await pool.query(
        `SELECT a.id, a.payload_json, a.submission_id, a.status AS application_status, s.user_id, s.intake_payload, s.status AS submission_status, s.submitted_at
           FROM iset_application a
           LEFT JOIN iset_application_submission s ON s.id = a.submission_id
          WHERE a.id = ?
          LIMIT 1`,
        [applicationId]
      );
      if (app) row = app;
      if (row) {
        const [[c]] = await pool.query(
          'SELECT id, status FROM iset_case WHERE application_id = ? LIMIT 1',
          [row.id]
        );
        if (c) caseRow = c;
      }
    }
    if (!row && applicantId) {
      const [[app]] = await pool.query(
        `SELECT a.id, a.payload_json, a.submission_id, a.status AS application_status, s.user_id, s.intake_payload, s.status AS submission_status, s.submitted_at
           FROM iset_application a
           LEFT JOIN iset_application_submission s ON s.id = a.submission_id
          WHERE s.user_id = ?
          ORDER BY a.created_at DESC
          LIMIT 1`,
        [applicantId]
      );
      if (app) row = app;
      if (row) {
        const [[c]] = await pool.query(
          'SELECT id, status FROM iset_case WHERE application_id = ? LIMIT 1',
          [row.id]
        );
        if (c) caseRow = c;
      }
    }
    if (caseRow) {
      caseMeta.status = caseRow.status || null;
    }
    const applicationStatusFromApplication = row?.application_status || null;
    const applicationStatusFromCase = caseRow?.status || null;
    caseMeta.application_status = applicationStatusFromApplication || applicationStatusFromCase || null;
    if (!row) return { answers: null, applicationId: null, submissionStatus: null, submittedAt: null, caseId: null, assessmentSubmitted: false, assessmentComplete: false, caseStatus: null, applicationStatus: null };
    let payload = row.payload_json;
    if (typeof payload === 'string') {
      try { payload = JSON.parse(payload); } catch { payload = {}; }
    }
    if (!payload || typeof payload !== 'object') payload = {};
    let answers = payload.answers || payload.form_answers || payload.data || null;
    if (!answers && row.intake_payload) {
      let intake = row.intake_payload;
      if (typeof intake === 'string') {
        try { intake = JSON.parse(intake); } catch { intake = null; }
      }
      if (intake && typeof intake === 'object') {
        answers = intake.answers || intake.form_answers || intake.data || intake;
      }
    }
    const normalizedAnswers = answers && typeof answers === 'object' ? answers : null;
    let assessmentSubmitted = false;
    let assessmentComplete = false;
    let assessmentLivingAllowance = 0;
    let assessmentDurationDays = null;
    let assessmentCostTotal = null;
    let assessmentHasTrainingCosts = false;
    let disabilitySupportRequested = false;
    const caseId = caseRow?.id || null;
    if (caseId) {
      try {
        const [[assess]] = await pool.query(
          'SELECT recommendation, date_of_assessment, itp_payload, intervention_duration_days, intervention_cost_total FROM iset_case_assessment WHERE case_id = ? LIMIT 1',
          [caseId]
        );
        assessmentSubmitted = !!assess;
        if (assess) {
          const hasRecommendation = assess.recommendation !== null && assess.recommendation !== undefined;
          const hasDate = assess.date_of_assessment !== null && assess.date_of_assessment !== undefined;
          assessmentComplete = hasRecommendation && hasDate;
          assessmentDurationDays = Number(assess.intervention_duration_days) || null;
          assessmentCostTotal = Number.isFinite(Number(assess.intervention_cost_total))
            ? Number(assess.intervention_cost_total)
            : null;
          try {
            let itp = assess.itp_payload;
            if (typeof itp === 'string') {
              try { itp = JSON.parse(itp); } catch { itp = null; }
            }
            if (Array.isArray(itp)) {
              itp.forEach(entry => {
                const cat = String(entry?.category || entry?.label || '').toLowerCase();
                const amt = Number(entry?.amount || entry?.value || 0);
                if (cat.includes('living') && cat.includes('allowance') && Number.isFinite(amt)) {
                  assessmentLivingAllowance += amt;
                }
                if (
                  Number.isFinite(amt) &&
                  amt > 0 &&
                  (cat.includes('tuition') ||
                    cat.includes('book') ||
                    cat.includes('material') ||
                    cat.includes('equipment') ||
                    cat.includes('fee'))
                ) {
                  assessmentHasTrainingCosts = true;
                }
                if (cat.includes('disability') && Number.isFinite(amt) && amt > 0) {
                  disabilitySupportRequested = true;
                }
              });
            }
          } catch (_) {
            assessmentLivingAllowance = 0;
            disabilitySupportRequested = false;
            assessmentHasTrainingCosts = false;
          }
        }
      } catch (_) {
        assessmentSubmitted = false;
        assessmentComplete = false;
        assessmentLivingAllowance = 0;
        assessmentDurationDays = null;
        assessmentCostTotal = null;
        assessmentHasTrainingCosts = false;
        disabilitySupportRequested = false;
      }
    }
    const numericFromAnswers = (keys = []) => {
      if (!Array.isArray(keys)) return null;
      for (const key of keys) {
        const raw = normalizedAnswers && normalizedAnswers[key];
        const value = Array.isArray(raw) ? raw[0] : raw;
        if (value === null || typeof value === 'undefined') continue;
        const num = Number.parseFloat(
          typeof value === 'string' ? value.replace(/[^0-9.+-]/g, '') : value
        );
        if (Number.isFinite(num)) return num;
      }
      return null;
    };
    const bandFundingAmount = numericFromAnswers(['income-band-funding', 'income_band_funding', 'income-band-funding-amount']);
    const socialAssistanceAmount = numericFromAnswers(['income-social-assistance', 'income_social_assistance', 'income-social-assistance-amount']);
    const targetProgramValueRaw = normalizedAnswers?.['target-program'] || normalizedAnswers?.['target_program'] || null;
    const targetProgramValue = Array.isArray(targetProgramValueRaw)
      ? String(targetProgramValueRaw[0] || '').toLowerCase()
      : String(targetProgramValueRaw || '').toLowerCase();
    const incomeKeys = [
      'income-employment',
      'income_employment',
      'income-employment_spousal',
      'income-spousal',
      'income_spousal',
      'income-other',
      'income_other',
      'income-band-funding',
      'income_band_funding',
      'income-social-assistance',
      'income_social_assistance'
    ];
    const expenseKeys = [
      'expenses-rent',
      'expenses_rent',
      'expenses-lease',
      'expenses_lease',
      'expenses-mortgage',
      'expenses_mortgage',
      'expenses-electricity',
      'expenses_electricity',
      'expenses-utilities',
      'expenses_utilities',
      'expenses-transportation',
      'expenses_transportation',
      'expenses-childcare',
      'expenses_childcare',
      'expenses-other',
      'expenses_other'
    ];
    const sumValues = keys => keys.reduce((sum, key) => {
      const val = numericFromAnswers([key]);
      return Number.isFinite(val) ? sum + val : sum;
    }, 0);
    const totalIncome = sumValues(incomeKeys);
    const totalExpenses = sumValues(expenseKeys);
    const hasIncome = totalIncome > 0;
    const hasExpenses = totalExpenses > 0;
    return {
      answers: normalizedAnswers,
      applicationId: row.id || null,
      submissionStatus: row.submission_status || null,
      submittedAt: row.submitted_at || null,
      caseId,
      assessmentSubmitted,
      assessmentComplete,
      caseStatus: caseMeta.status || null,
      applicationStatus: caseMeta.application_status || null,
      assessmentLivingAllowance,
      assessmentDurationDays,
      assessmentCostTotal,
      assessmentHasTrainingCosts,
      disabilitySupportRequested,
      bandFundingAmount,
      socialAssistanceAmount,
      hasIncome,
      hasExpenses,
      targetProgramValue
    };
  } catch (err) {
    console.warn('[checklist] failed to load application answers', err?.message || err);
    return {
      answers: null,
      applicationId: null,
      submissionStatus: null,
      submittedAt: null,
      caseId: null,
      assessmentSubmitted: false,
      assessmentComplete: false,
      caseStatus: null,
      applicationStatus: null,
      assessmentLivingAllowance: 0,
      assessmentDurationDays: null,
      assessmentCostTotal: null,
      assessmentHasTrainingCosts: false,
      disabilitySupportRequested: false,
      bandFundingAmount: null,
      socialAssistanceAmount: null,
      hasIncome: false,
      hasExpenses: false,
      targetProgramValue: ''
    };
  }
}

function applicationDocTypeSatisfied(docType, answers) {
  if (!answers || typeof answers !== 'object') return false;
  switch (docType) {
    case 'ei_consent':
      return Boolean(answers?.consent && answers.consent.signed);
    case 'indigenous_declaration':
      return Boolean(answers?.indigenous_declaration && answers.indigenous_declaration.signed);
    case 'conflict_of_interest':
      return Boolean(answers?.conflict_applicant_signature && answers.conflict_applicant_signature.signed);
    default:
      return false;
  }
}

function parseMetadata(raw) {
  if (!raw) return null;
  if (typeof raw === 'object') return raw;
  if (typeof raw === 'string') {
    try {
      return JSON.parse(raw);
    } catch (_) {
      return null;
    }
  }
  return null;
}

function ensureDirectoryExists(dirPath) {
  try {
    fs.mkdirSync(dirPath, { recursive: true });
  } catch (err) {
    if (err && err.code !== 'EEXIST') {
      console.warn('[admin:uploads] failed to ensure directory %s: %s', dirPath, err.message);
      throw err;
    }

  }
}

ensureDirectoryExists(INTAKE_UPLOADS_ROOT);
ensureDirectoryExists(ADMIN_MANUAL_UPLOAD_DIR);

function toIntakeRelativePath(absolutePath) {
  if (!absolutePath) return null;
  const relative = path.relative(INTAKE_ROOT, absolutePath);
  return relative ? relative.replace(/\\/g, '/') : null;
}

function sanitiseUploadFilename(originalName) {
  const fallback = 'document';
  if (!originalName || typeof originalName !== 'string') {
    return `${fallback}-${Date.now()}-${crypto.randomBytes(4).toString('hex')}.bin`;
  }
  const parsed = path.parse(originalName);
  const base = parsed.name ? parsed.name.replace(/[^a-z0-9_\-]+/gi, '_').slice(0, 80) : fallback;
  const ext = parsed.ext && parsed.ext.length <= 10 ? parsed.ext.toLowerCase() : '';
  const hash = crypto.randomBytes(4).toString('hex');
  const timestamp = Date.now();
  const safeBase = base || fallback;
  return `${safeBase}-${timestamp}-${hash}${ext}`;
}

const adminUploadStorage = multer.diskStorage({
  destination: (_req, _file, cb) => cb(null, ADMIN_MANUAL_UPLOAD_DIR),
  filename: (_req, file, cb) => cb(null, sanitiseUploadFilename(file.originalname))
});

const adminUploadFileFilter = (_req, file, cb) => {
  if (ADMIN_UPLOAD_ALLOWED_MIME_TYPES.has(file.mimetype)) {
    cb(null, true);
  } else {
    const error = new Error('unsupported_file_type');
    error.code = 'UNSUPPORTED_FILE_TYPE';
    cb(error);
  }
};

const adminDocumentUpload = multer({
  storage: adminUploadStorage,
  limits: { fileSize: ADMIN_UPLOAD_MAX_BYTES },
  fileFilter: adminUploadFileFilter
});

const resolveUploadStorageMode = () => {
  const storageModeEnv = (process.env.UPLOAD_MODE || process.env.UPLOAD_DRIVER || '').toLowerCase();
  return storageModeEnv === 's3' ? 's3' : 'local-direct';
};

function computeFileSha256(filePath) {
  return new Promise((resolve, reject) => {
    if (!filePath) return resolve(null);
    const hash = crypto.createHash('sha256');
    const stream = fs.createReadStream(filePath);
    stream.on('data', chunk => hash.update(chunk));
    stream.on('end', () => {
      try {
        resolve(hash.digest('hex'));
      } catch (err) {
        resolve(null);
      }
    });
    stream.on('error', err => {
      console.warn('[admin:uploads] checksum failed for %s: %s', filePath, err.message);
      resolve(null);
    });
  });
}

async function duplicateDocumentFile({ filePath, fileName, applicantUserId }) {
  if (!filePath) {
    throw new Error('missing_file_path');
  }
  const storageMode = resolveUploadStorageMode();
  if (storageMode === 's3') {
    const { generateKey, copyObject, DRIVER } = require('../ISET-intake/s3Provider');
    if (DRIVER !== 's3' || typeof copyObject !== 'function') {
      throw new Error('s3_copy_unavailable');
    }
    const key = generateKey(applicantUserId || 'admin', fileName || 'document');
    await copyObject({ sourceKey: filePath, targetKey: key });
    return key;
  }
  const normalized = String(filePath).replace(/\\/g, '/').replace(/^\/+/, '');
  const sourcePath = path.join(INTAKE_ROOT, normalized);
  const targetName = sanitiseUploadFilename(fileName || 'document');
  const targetPath = path.join(ADMIN_MANUAL_UPLOAD_DIR, targetName);
  await fs.promises.copyFile(sourcePath, targetPath);
  return toIntakeRelativePath(targetPath);
}

function normalisePositiveInteger(value) {
  if (value === null || typeof value === 'undefined') return null;
  const asNumber = Number(value);
  if (!Number.isFinite(asNumber)) return null;
  const int = Math.trunc(asNumber);
  return int > 0 ? int : null;
}

const clampReminderMinutes = (value) => {
  const parsed = normalisePositiveInteger(value);
  const minutes = parsed || DEFAULT_BACKEND_JOBS_CONFIG.reminderPollMinutes;
  // Bound between 1 minute and 24 hours to avoid runaway intervals
  return Math.min(Math.max(minutes, 1), 24 * 60);
};

const reminderMinutesToMs = minutes => clampReminderMinutes(minutes) * 60 * 1000;

function resolveAdminActorUserId(req) {
  if (!req || typeof req !== 'object') return null;
  const candidates = [
    req.staffProfile?.user_id,
    req.staffProfile?.id,
    req.auth?.staffProfileId,
    req.auth?.userId,
    req.auth?.id,
    req.auth?.sub,
    req.headers?.['x-dev-userid'],
    req.headers?.['x-dev-user-id'],
    req.headers?.['x-dev-user_id']
  ];
  for (const candidate of candidates) {
    const normalised = normalisePositiveInteger(candidate);
    if (normalised !== null) return normalised;
  }
  return null;
}

function escapeHtml(value) {
  if (value === null || value === undefined) return '';
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

