function extractAgreementNumber(context) {
  const { answers = {}, actionPlan = {}, caseActionPlans = [] } = context || {};
  const resolvedPlan = (() => {
    if (actionPlan && Object.keys(actionPlan).length) return actionPlan;
    if (!Array.isArray(caseActionPlans) || !caseActionPlans.length) return null;
    const priorities = { active: 0, ready_to_close: 1, closed: 2, draft: 3 };
    return [...caseActionPlans]
      .sort((a, b) => {
        const pa = priorities[(a.status || '').toLowerCase()] ?? 4;
        const pb = priorities[(b.status || '').toLowerCase()] ?? 4;
        if (pa !== pb) return pa - pb;
        const da = a.activatedAt || a.effectiveDate || a.createdAt || null;
        const db = b.activatedAt || b.effectiveDate || b.createdAt || null;
        if (da && db) {
          const diff = new Date(db).getTime() - new Date(da).getTime();
          if (Number.isFinite(diff) && diff !== 0) return diff < 0 ? -1 : 1;
        }
        return (b.id || 0) - (a.id || 0);
      })
      [0];
  })() || {};

  const planAgreement =
    resolvedPlan.agreementNumber ||
    resolvedPlan.agreement_number ||
    (resolvedPlan.esdc && resolvedPlan.esdc.agreementNumber) ||
    null;
  const rawAgreement = normaliseString(
    planAgreement ||
    answers['agreement-number'] ||
    answers['agreement_number']
  );

  const digitsOnly = value => (value ? String(value).replace(/\D/g, '') : '');
  const placeholder = '999999999'; // temporary until finance module supplies real agreement numbers

  if (rawAgreement) {
    const numeric = digitsOnly(rawAgreement);
    if (numeric.length >= 7 && numeric.length <= 9) {
      return numeric;
    }
  }

  const fundingStream =
    resolvedPlan.fundingStream ||
    resolvedPlan.funding_stream ||
    (resolvedPlan.esdc && resolvedPlan.esdc.fundingStream) ||
    null;
  const derived = deriveAgreementNumberFromFundingStream(fundingStream);
  if (derived && derived !== placeholder) return derived;

  return placeholder;
}

const deriveAgreementNumberFromEiClaimant = eiClaimantCode => {
  const code = typeof eiClaimantCode === 'string' ? eiClaimantCode.trim() : eiClaimantCode;
  if (code === '1' || code === 1 || code === '2' || code === 2) {
    // EI-funded agreements
    return '16535866';
  }
  if (code === '3' || code === 3) {
    // CRF-funded agreements
    return '16535841';
  }
  return '999999999';
};

const deriveAgreementNumberFromFundingStream = fundingStream => {
  const key = typeof fundingStream === 'string' ? fundingStream.trim().toUpperCase() : '';
  if (key === 'EI') return '16535866';
  if (key === 'CRF') return '16535841';
  return '999999999';
};

function extractClientStatusDetails(context) {
  const { answers = {}, caseContext = {} } = context;
  const rawStatus = normaliseString(
    caseContext.employmentStatus ||
    caseContext.labourForceStatus ||
    answers['client-status-at-intake'] ||
    answers['client_status_at_intake'] ||
    answers['labour-force-status'] ||
    answers['labour_force_status']
  );
  const casePrevEmployment = caseContext.prevEmployment || caseContext.prevEmploymentCode;
  const prevEmploymentCode = (() => {
    if (casePrevEmployment === null || typeof casePrevEmployment === 'undefined') return null;
    const str = String(casePrevEmployment).trim();
    if (!str) return null;
    if (['1', '2', '9'].includes(str)) return str;
    return null;
  })();
  const key = rawStatus ? rawStatus.toLowerCase() : null;
  const statusLabel = key ? (CLIENT_STATUS_MAP[key] || rawStatus) : null;
  const scheduleKey = key || '';
  const scheduleType = EMPLOYMENT_SCHEDULE_MAP[scheduleKey] || null;
  const noc = normaliseString(
    answers['employment-noc'] ||
    answers['employment_noc'] ||
    answers['previous-employment-noc']
  );
  const nocVersion = normaliseString(
    answers['employment-noc-version'] ||
    answers['employment_noc_version'] ||
    answers['previous-employment-noc-version']
  );
  return {
    status: statusLabel || null,
    scheduleType: scheduleType,
    noc: noc || null,
    nocVersion: nocVersion || null,
    prevEmployment: prevEmploymentCode
  };
}

function mapPrevEmploymentFromStatus(status) {
  if (!status) return null;
  const key = String(status).trim().toLowerCase();
  if (key === 'unemployed' || key === 'underemployed') return 1;
  if (key === 'student') return 9;
  if (key.startsWith('employed') || key === 'self-employed' || key === 'self employed') return 2;
  return null;
}

