app.get('/api/finance/transactions', async (req, res) => {
  if (requireFinanceRole(req, res)) return;
  try {
    const { potId, potIds, caseId, interventionId, limit = 100 } = req.query || {};
    const where = [];
    const params = [];
    const parsedPotIds = [];
    if (Array.isArray(potIds)) {
      potIds.forEach(id => {
        const num = Number(id);
        if (Number.isFinite(num)) parsedPotIds.push(num);
      });
    } else if (typeof potIds === 'string') {
      potIds
        .split(',')
        .map(s => s.trim())
        .forEach(id => {
          const num = Number(id);
          if (Number.isFinite(num)) parsedPotIds.push(num);
        });
    }
    const singlePotId = Number(potId);
    if (Number.isFinite(singlePotId)) {
      parsedPotIds.push(singlePotId);
    }
    const uniquePotIds = Array.from(new Set(parsedPotIds));
    if (uniquePotIds.length === 1) {
      where.push('ft.budget_pot_id = ?');
      params.push(uniquePotIds[0]);
    } else if (uniquePotIds.length > 1) {
      const placeholders = uniquePotIds.map(() => '?').join(',');
      where.push(`ft.budget_pot_id IN (${placeholders})`);
      params.push(...uniquePotIds);
    }
    if (caseId) {
      where.push('ft.case_id = ?');
      params.push(Number(caseId));
    }
    if (interventionId) {
      where.push('ft.case_intervention_id = ?');
      params.push(Number(interventionId));
    }
    const whereClause = where.length ? `WHERE ${where.join(' AND ')}` : '';
    const cappedLimit = Math.min(Number(limit) || 100, 500);
    const [rows] = await pool.query(
      `SELECT ft.id, ft.case_id, ft.case_intervention_id, ft.budget_pot_id, ft.amount, ft.currency, ft.status, ft.transaction_date, ft.created_at, ft.updated_at,
              bp.name AS pot_name, bp.code AS pot_code
         FROM finance_transaction ft
         LEFT JOIN budget_pot bp ON bp.id = ft.budget_pot_id
        ${whereClause}
        ORDER BY ft.updated_at DESC
        LIMIT ?`,
      [...params, cappedLimit]
    );
    const mapped = rows.map(row => ({
      id: row.id,
      caseId: row.case_id,
      interventionId: row.case_intervention_id,
      potId: row.budget_pot_id,
      potName: row.pot_name,
      potCode: row.pot_code,
      amount: Number(row.amount || 0),
      currency: row.currency || 'CAD',
      status: row.status,
      transactionDate: row.transaction_date,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    }));
    res.status(200).json(mapped);
  } catch (err) {
    console.error('[finance] failed to list transactions', err);
    res.status(500).json({ error: 'failed_to_list_transactions' });
  }
});

